from typing import List

class Solution:
    def rob(self, nums: List[int]) -> int:
        def dfs(i: int) -> int:
            if i >= len(nums):
                return 0
            return max(nums[i] + dfs(i + 2), dfs(i + 1))

        return dfs(0)

