from typing import List

class Solution:
    def rob(self, nums: List[int]) -> int:
        memo = {}

        def dfs(i: int) -> int:
            if i >= len(nums):
                return 0
            if i not in memo:
                memo[i] = max(nums[i] + dfs(i + 2), dfs(i + 1))
            return memo[i]

        return dfs(0)

