from typing import List

class Solution:
    def rob(self, nums: List[int]) -> int:
        rob_prev, skip_prev = 0, 0
        for money in nums:
            new_rob = skip_prev + money
            new_skip = max(skip_prev, rob_prev)
            rob_prev, skip_prev = new_rob, new_skip
        return max(rob_prev, skip_prev)

